def pasar_a_ocultas_un_rato(apps, schema_editor):
    """
    Las fuentes que estaban ocultas por fallar en los aparatos (antes, siempre
    7 días) pasan a la regla nueva (models.OCULTA_POR): como primera vez, 3
    horas desde que se ocultaron; las que ya pasaron ese tiempo vuelven a la
    app enseguida. Las que los aparatos no pueden leer (formato) siguen la semana.
    """
    Fuente = apps.get_model('canales', 'Fuente')
    cambiadas = []
    for fuente in Fuente.objects.filter(oculta_desde__isnull=False).only('pk', 'oculta_desde', 'falla_en_aparatos'):
        de_formato = fuente.falla_en_aparatos.startswith('el aparato no puede leer el formato')
        fuente.oculta_hasta = fuente.oculta_desde + (timedelta(days=7) if de_formato else timedelta(hours=3))
        fuente.veces_oculta = 1
        cambiadas.append(fuente)
    Fuente.objects.bulk_update(cambiadas, ['oculta_hasta', 'veces_oculta'], batch_size=500)


